import{_t as e,it as t,n,rt as r}from"./chunks/framework.rZZZX73S.js";var i=JSON.parse(`{"title":"Plugin kit","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/plugin-kit/docs/index.md"},"headers":[],"relativePath":"tools/plugin-kit/docs/index.md","filePath":"tools/plugin-kit/docs/index.md","lastUpdated":1791457168000}`),a={name:`tools/plugin-kit/docs/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plugin-kit" tabindex="-1">Plugin kit <a class="header-anchor" href="#plugin-kit" aria-label="Permalink to “Plugin kit”">​</a></h1><p><code>@pumpkin-plugins/plugin-kit</code> contains shared lifecycle, scheduling, command, logging, data-folder, plugin-message, and payload helpers used by Pumpkin plugins. It also provides in-memory fakes for testing code that depends on host services.</p><h2 id="plugin-lifecycle" tabindex="-1">Plugin lifecycle <a class="header-anchor" href="#plugin-lifecycle" aria-label="Permalink to “Plugin lifecycle”">​</a></h2><p>Extend <code>PluginBase</code> with the package&#39;s <code>PluginInfo</code> and version, implement the plugin load hook, then register the instance. The shared registration adds the non-blocking Pumpkin Market update check. Plugin entry points export <code>handleTask</code> so shared scheduled work is dispatched before the Pumpkin API&#39;s task handler.</p><p>The scheduler helpers use whole, nonnegative tick counts and require repeating intervals of at least one tick. Delayed callbacks are released before execution; failed scheduling does not retain them. Tick delays and periods are sent to WIT as <code>bigint</code>; handler and task IDs remain <code>number</code>.</p><h2 id="data-and-commands" tabindex="-1">Data and commands <a class="header-anchor" href="#data-and-commands" aria-label="Permalink to “Data and commands”">​</a></h2><p>The WASI data-folder adapter supplies file listing, random-access reads, directory creation, and atomic file replacement. Paths are relative to the plugin data mount. The shared command helpers register a typed command tree and derive the documented command paths from that same declaration.</p><p>Use the <code>MemoryFiles</code>, fake command registry, and logger helpers in unit tests. Their behavior intentionally catches common host mismatches such as writing to a missing directory, conflicting file and directory paths, or using a file handle after close. The generated API reference lists the package&#39;s module entry points and exact types.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};